# Ported from: mistral/data/pretokenized/image_transform_metadata.py
# ImageBoundingBox simplified from: shared/geometry.py (ImageBoundingBox).
# Keep the same top_left/bottom_right structure as Mistral so epoch indexes
# generated by this fork are readable by the Mistral reference loader.

import dataclasses
import json
from typing import Any, NamedTuple

NONE_BOUNDING_BOX = "none_bbox"


class Point(NamedTuple):
    x: float
    y: float


class ImageBoundingBox:
    __slots__ = (
        "top_left",
        "bottom_right",
        "label",
        "caption",
        "image_idx",
        "meta",
        "is_masked",
    )

    def __init__(
        self,
        top_left: Point | tuple[float, float] | list[float] | None = None,
        bottom_right: Point | tuple[float, float] | list[float] | None = None,
        label: str | None = None,
        caption: Any | None = None,
        image_idx: int | None = None,
        meta: dict[str, Any] | None = None,
        is_masked: bool = False,
        *,
        top_left_x: float | None = None,
        top_left_y: float | None = None,
        bottom_right_x: float | None = None,
        bottom_right_y: float | None = None,
    ) -> None:
        if top_left is None or bottom_right is None:
            assert top_left_x is not None, "Expected top_left or top_left_x"
            assert top_left_y is not None, "Expected top_left or top_left_y"
            assert bottom_right_x is not None, "Expected bottom_right or bottom_right_x"
            assert bottom_right_y is not None, "Expected bottom_right or bottom_right_y"
            top_left = Point(top_left_x, top_left_y)
            bottom_right = Point(bottom_right_x, bottom_right_y)

        self.top_left = self._coerce_point(top_left)
        self.bottom_right = self._coerce_point(bottom_right)
        self.label = label
        self.caption = caption
        self.image_idx = image_idx
        self.meta = meta
        self.is_masked = is_masked

    @staticmethod
    def _coerce_point(point: Point | tuple[float, float] | list[float]) -> Point:
        return Point(float(point[0]), float(point[1]))

    @property
    def top_left_x(self) -> float:
        return self.top_left.x

    @property
    def top_left_y(self) -> float:
        return self.top_left.y

    @property
    def bottom_right_x(self) -> float:
        return self.bottom_right.x

    @property
    def bottom_right_y(self) -> float:
        return self.bottom_right.y

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ImageBoundingBox):
            return NotImplemented
        return self.to_mistral_dict() == other.to_mistral_dict()

    def to_mistral_dict(self) -> dict[str, Any]:
        return {
            "label": self.label,
            "caption": self.caption,
            "image_idx": self.image_idx,
            "meta": self.meta,
            "is_masked": self.is_masked,
            "top_left": [self.top_left.x, self.top_left.y],
            "bottom_right": [self.bottom_right.x, self.bottom_right.y],
        }

    def to_mistral_json(self) -> str:
        return json.dumps(
            self.to_mistral_dict(), ensure_ascii=False, separators=(",", ":")
        )

    @classmethod
    def from_mistral_dict(cls, d: dict[str, Any]) -> "ImageBoundingBox":
        top_left = d["top_left"]
        bottom_right = d["bottom_right"]
        if "page_height" in d and "page_width" in d and d["page_width"] is not None:
            page_height = d["page_height"]
            page_width = d["page_width"]
            top_left = (top_left[0] / page_width, top_left[1] / page_height)
            bottom_right = (
                bottom_right[0] / page_width,
                bottom_right[1] / page_height,
            )
        return cls(
            top_left=Point(float(top_left[0]), float(top_left[1])),
            bottom_right=Point(float(bottom_right[0]), float(bottom_right[1])),
            label=d.get("label"),
            caption=d.get("caption"),
            image_idx=d.get("image_idx"),
            meta=d.get("meta"),
            is_masked=bool(d.get("is_masked", False)),
        )

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "ImageBoundingBox":
        if "top_left" in d:
            return cls.from_mistral_dict(d)
        return cls(
            top_left_x=d["top_left_x"],
            top_left_y=d["top_left_y"],
            bottom_right_x=d["bottom_right_x"],
            bottom_right_y=d["bottom_right_y"],
        )


@dataclasses.dataclass
class TransformImageMetadata:
    width: int
    height: int

    # L2 reconstruction score for DynamicResizeTransform / SometimesHighResTransform.
    # Keyed by DynamicResizeTransform.args_to_dict_key() e.g. "image_min_size=224,l2_resize_factor=2"
    l2_reconstruction_score: dict[str, float] = dataclasses.field(default_factory=dict)

    # Bounding box of non-background content for Trim transform (OCR pipeline).
    _img_bbox_for_trim: ImageBoundingBox | None = None
    img_bbox_for_trim_is_computed: bool = False

    # Kept for epoch-index wire compatibility with Mistral.
    vision_classifier_metadata: Any | None = None

    @property
    def size(self) -> tuple[int, int]:
        return (self.height, self.width)

    @property
    def img_bbox_for_trim(self) -> ImageBoundingBox | None:
        if not self.img_bbox_for_trim_is_computed:
            raise ValueError("img_bbox_for_trim is not computed yet")
        return self._img_bbox_for_trim

    @img_bbox_for_trim.setter
    def img_bbox_for_trim(
        self, value: ImageBoundingBox | dict[str, Any] | str | None
    ) -> None:
        if value == NONE_BOUNDING_BOX:
            value = None
        elif isinstance(value, dict):
            value = ImageBoundingBox.from_dict(value)
        assert value is None or isinstance(value, ImageBoundingBox), (
            f"Expected ImageBoundingBox, {NONE_BOUNDING_BOX!r}, or None, got {value!r}"
        )
        self._img_bbox_for_trim = value
        self.img_bbox_for_trim_is_computed = True
